# Wire one DLZ_REPO_ROOT for OpenClaw (Windows) + AutoGPT Docker volume paths.
# Usage: .\setup-dlz-shared-workspace.ps1 -RepoRoot C:\Dev\push
param(
    [Parameter(Mandatory = $true)]
    [string] $RepoRoot
)

$ErrorActionPreference = "Stop"
$RepoRoot = (Resolve-Path $RepoRoot).Path
$OpenClaw = Join-Path $env:USERPROFILE ".openclaw"
New-Item -ItemType Directory -Force -Path $OpenClaw | Out-Null

$local = @"
# Generated by setup-dlz-shared-workspace.ps1 — do not commit
`$env:DLZ_REPO_ROOT = "$($RepoRoot -replace '\\','/')"
"@

$localPath = Join-Path $OpenClaw "disklordz.local.ps1"
if (Test-Path $localPath) {
    $existing = Get-Content $localPath -Raw
    if ($existing -notmatch "DLZ_REPO_ROOT") {
        Add-Content -Path $localPath -Value "`n$local"
    }
} else {
    Set-Content -Path $localPath -Value $local
}

$releases = Join-Path $RepoRoot "Assets\Releases"
New-Item -ItemType Directory -Force -Path $releases | Out-Null

$autogptEnv = Join-Path $RepoRoot "openclaw\autogpt\.env"
@"
DLZ_WIN_ROOT=$($RepoRoot -replace '\\','/')
FIRECRAWL_API_KEY=
AUTOGPT_MAX_ITERATIONS=8
"@ | Set-Content -Path $autogptEnv -Encoding utf8

Write-Host "DLZ_REPO_ROOT -> $RepoRoot"
Write-Host "OpenClaw: $localPath"
Write-Host "AutoGPT env: $autogptEnv (copy values into autogpt_platform/.env)"
Write-Host "Releases: $releases"
Write-Host "Merge volumes: openclaw/autogpt/docker-compose.volumes.example.yml"